<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { ArrowRight, ShieldCheck, Sprout } from 'lucide-vue-next';
import { useAuthStore } from '../stores/auth'; import { errorMessage } from '../services/api'; import AppInput from '../components/ui/AppInput.vue'; import AppButton from '../components/ui/AppButton.vue'; import AppForm from '../components/forms/AppForm.vue';
const auth = useAuthStore(); const router = useRouter(); const email = ref(''); const password = ref(''); const busy = ref(false); const error = ref('');
async function submit() { busy.value = true; error.value = ''; try { await auth.login(email.value, password.value); await router.push(auth.user?.mustChangePassword ? '/change-password' : auth.isStaff ? '/' : '/my-profile'); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
</script>
<template><div class="auth-page"><section class="auth-story"><div class="brand"><span class="brand-mark"><Sprout /></span>somity.</div><div><span class="eyebrow light">STRONGER, TOGETHER</span><h1>A little more connected.<br>A lot more organized.</h1><p>A thoughtful home for your society’s members.<br>Keep the details in order, and your community in focus.</p><div class="story-art" aria-hidden="true"><span class="art-ring r1"></span><span class="art-ring r2"></span><span class="art-ring r3"></span><Sprout :size="92" :stroke-width="1" /></div></div><small><ShieldCheck :size="16" /> Private access for your society</small></section><section class="auth-panel"><div class="auth-card"><span class="eyebrow">WELCOME TO SOMITY</span><h2>Good to see you.</h2><p class="muted">Sign in to your society workspace.</p><AppForm :error="error" :busy="busy" @submit="submit"><AppInput v-model="email" label="Email address" type="email" placeholder="you@example.com" autocomplete="username" required maxlength="191" /><AppInput v-model="password" label="Password" type="password" autocomplete="current-password" required maxlength="128" /><AppButton type="submit" :loading="busy" class="full-width">Sign in <ArrowRight :size="17" /></AppButton></AppForm><div class="auth-help">Need access? Contact your society administrator.</div></div><small class="auth-copyright">Somity · A simpler way to manage your community</small></section></div></template>
